const nonEmptyItems = (nodeName) =>
  $(nodeName)
    .all()
    .map((item) => item.json)
    .filter((value) => value && typeof value === 'object' && Object.keys(value).length > 0);

const config = $('Sleeper League Form').first().json;
const user = nonEmptyItems('Resolve Sleeper User')[0] ?? {};
const league = nonEmptyItems('Get League')[0] ?? {};
const leagueUsers = nonEmptyItems('Get League Users');
const rosters = nonEmptyItems('Get Rosters');
const drafts = nonEmptyItems('Get League Drafts');
const tradedPicks = nonEmptyItems('Get Traded Picks');
const nflState = nonEmptyItems('Get NFL State')[0] ?? {};

const asString = (value, fallback = '—') => {
  if (value === null || value === undefined || value === '') return fallback;
  return String(value);
};

const escapeHtml = (value) =>
  asString(value, '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');

const formatDate = (value) => {
  if (value === null || value === undefined || value === '') return '—';
  const numeric = Number(value);
  const date = Number.isFinite(numeric) ? new Date(numeric) : new Date(value);
  return Number.isNaN(date.getTime()) ? asString(value) : date.toLocaleString('en-US');
};

const formatPoints = (base, decimal) => {
  if (base === null || base === undefined) return '—';
  const whole = Number(base);
  const fraction = Number(decimal ?? 0) / 100;
  if (!Number.isFinite(whole) || !Number.isFinite(fraction)) return asString(base);
  return (whole + fraction).toFixed(2);
};

const countValues = (values = []) => {
  const counts = new Map();
  for (const value of values) counts.set(value, (counts.get(value) ?? 0) + 1);
  return [...counts.entries()].map(([value, count]) => (count > 1 ? `${value} ×${count}` : value));
};

const usersById = new Map(
  leagueUsers
    .filter((entry) => entry.user_id !== null && entry.user_id !== undefined)
    .map((entry) => [String(entry.user_id), entry]),
);

const rostersById = new Map(
  rosters
    .filter((entry) => entry.roster_id !== null && entry.roster_id !== undefined)
    .map((entry) => [String(entry.roster_id), entry]),
);

const userTeamName = (leagueUser) =>
  leagueUser?.metadata?.team_name ||
  leagueUser?.metadata?.team_name_update ||
  leagueUser?.display_name ||
  'Unnamed Team';

const rosterDisplayName = (rosterId) => {
  const roster = rostersById.get(String(rosterId));
  if (!roster) return `Roster ${asString(rosterId)}`;
  const owner = usersById.get(String(roster.owner_id));
  return `${userTeamName(owner)} (Roster ${asString(rosterId)})`;
};

const userId = user.user_id === null || user.user_id === undefined ? null : String(user.user_id);
const selectedRoster =
  rosters.find(
    (roster) =>
      userId &&
      (String(roster.owner_id) === userId ||
        (Array.isArray(roster.co_owners) && roster.co_owners.map(String).includes(userId))),
  ) ?? null;

const rosterRows = [...rosters]
  .sort((a, b) =>
    String(a.roster_id ?? '').localeCompare(String(b.roster_id ?? ''), undefined, { numeric: true }),
  )
  .map((roster) => {
    const owner = usersById.get(String(roster.owner_id));
    const team = userTeamName(owner);
    const ownerName = owner?.display_name ?? (roster.owner_id ? `User ${roster.owner_id}` : 'Unassigned');
    const settings = roster.settings ?? {};
    const wins = settings.wins ?? 0;
    const losses = settings.losses ?? 0;
    const ties = settings.ties ?? 0;
    return {
      rosterId: asString(roster.roster_id),
      team,
      owner: ownerName,
      players: Array.isArray(roster.players) ? roster.players.length : 0,
      starters: Array.isArray(roster.starters) ? roster.starters.length : 0,
      reserve: Array.isArray(roster.reserve) ? roster.reserve.length : 0,
      taxi: Array.isArray(roster.taxi) ? roster.taxi.length : 0,
      record: `${wins}-${losses}${ties ? `-${ties}` : ''}`,
      pointsFor: formatPoints(settings.fpts, settings.fpts_decimal),
      waiverPosition: asString(settings.waiver_position),
      waiverBudgetUsed: asString(settings.waiver_budget_used),
    };
  });

const draftRows = drafts.map((draft) => ({
  draftId: asString(draft.draft_id),
  season: asString(draft.season),
  status: asString(draft.status),
  type: asString(draft.type),
  rounds: asString(draft.settings?.rounds),
  teams: asString(draft.settings?.teams),
  startTime: formatDate(draft.start_time),
}));

const tradedPickRows = tradedPicks
  .sort((a, b) => {
    const bySeason = String(a.season ?? '').localeCompare(String(b.season ?? ''), undefined, {
      numeric: true,
    });
    if (bySeason !== 0) return bySeason;
    return Number(a.round ?? 0) - Number(b.round ?? 0);
  })
  .map((pick) => ({
    season: asString(pick.season),
    round: asString(pick.round),
    originalRoster: rosterDisplayName(pick.roster_id),
    previousOwner: rosterDisplayName(pick.previous_owner_id),
    currentOwner: rosterDisplayName(pick.owner_id),
  }));

const rosterPositions = countValues(Array.isArray(league.roster_positions) ? league.roster_positions : []);

const leagueSettings = Object.entries(league.settings ?? {})
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([key, value]) => ({ key, value: asString(value) }));

const scoringHighlightsKeys = [
  'pass_yd',
  'pass_td',
  'pass_int',
  'rush_yd',
  'rush_td',
  'rec',
  'rec_yd',
  'rec_td',
  'fum_lost',
];
const scoringHighlights = scoringHighlightsKeys
  .filter((key) => Object.hasOwn(league.scoring_settings ?? {}, key))
  .map((key) => ({ key, value: asString(league.scoring_settings[key]) }));

const generatedAt = new Date().toISOString();
const leagueName = league.name ?? `Sleeper League ${config.leagueId}`;
const avatarUrl = user.avatar
  ? `https://sleepercdn.com/avatars/${encodeURIComponent(String(user.avatar))}`
  : null;

const markdownTable = (headers, rows) => {
  if (rows.length === 0) return '_No records returned._';
  const header = `| ${headers.join(' | ')} |`;
  const divider = `| ${headers.map(() => '---').join(' | ')} |`;
  const body = rows.map((row) => `| ${row.map((cell) => asString(cell).replaceAll('|', '\\|')).join(' | ')} |`);
  return [header, divider, ...body].join('\n');
};

const markdown = [
  `# ${leagueName} — Preseason League Command Center`,
  '',
  `Generated: ${generatedAt}`,
  '',
  '## League Overview',
  markdownTable(
    ['Field', 'Value'],
    [
      ['League ID', asString(league.league_id ?? config.leagueId)],
      ['Season', asString(league.season)],
      ['Status', asString(league.status)],
      ['Season Type', asString(league.season_type)],
      ['Teams', asString(league.total_rosters ?? rosters.length)],
      ['Previous League ID', asString(league.previous_league_id)],
      ['Primary Draft ID', asString(league.draft_id)],
    ],
  ),
  '',
  '## Current NFL State',
  markdownTable(
    ['Field', 'Value'],
    [
      ['Season', asString(nflState.season)],
      ['Season Type', asString(nflState.season_type)],
      ['Week', asString(nflState.week)],
      ['Display Week', asString(nflState.display_week)],
      ['League Season', asString(nflState.league_season)],
      ['Previous Season', asString(nflState.previous_season)],
    ],
  ),
  '',
  '## Selected Sleeper User',
  markdownTable(
    ['Field', 'Value'],
    [
      ['Display Name', asString(user.display_name)],
      ['Username', asString(user.username)],
      ['User ID', asString(user.user_id)],
      ['League Team', selectedRoster ? userTeamName(usersById.get(String(selectedRoster.owner_id))) : 'No matching roster'],
      ['Roster ID', selectedRoster ? asString(selectedRoster.roster_id) : '—'],
      ['Avatar URL', avatarUrl ?? '—'],
    ],
  ),
  '',
  '## Teams and Rosters',
  markdownTable(
    ['Roster', 'Team', 'Owner', 'Players', 'Starters', 'Reserve', 'Taxi', 'Record', 'Points For'],
    rosterRows.map((row) => [
      row.rosterId,
      row.team,
      row.owner,
      row.players,
      row.starters,
      row.reserve,
      row.taxi,
      row.record,
      row.pointsFor,
    ]),
  ),
  '',
  '## Drafts',
  markdownTable(
    ['Season', 'Status', 'Type', 'Rounds', 'Teams', 'Start Time', 'Draft ID'],
    draftRows.map((row) => [
      row.season,
      row.status,
      row.type,
      row.rounds,
      row.teams,
      row.startTime,
      row.draftId,
    ]),
  ),
  '',
  '## Traded Draft Picks',
  markdownTable(
    ['Season', 'Round', 'Original Roster', 'Previous Owner', 'Current Owner'],
    tradedPickRows.map((row) => [
      row.season,
      row.round,
      row.originalRoster,
      row.previousOwner,
      row.currentOwner,
    ]),
  ),
  '',
  '## Roster Sleeper League Form',
  rosterPositions.length ? rosterPositions.join(', ') : '_No roster positions returned._',
  '',
  '## Scoring Highlights',
  markdownTable(
    ['Setting', 'Value'],
    scoringHighlights.map((row) => [row.key, row.value]),
  ),
  '',
  '## League Settings',
  markdownTable(
    ['Setting', 'Value'],
    leagueSettings.map((row) => [row.key, row.value]),
  ),
  '',
  '> Generated with the unofficial n8n-nodes-sleeper community node. Sleeper data is public and read-only.',
].join('\n');

const htmlTable = (headers, rows) => {
  if (rows.length === 0) return '<p class="empty">No records returned.</p>';
  return `<div class="table-wrap"><table><thead><tr>${headers
    .map((header) => `<th>${escapeHtml(header)}</th>`)
    .join('')}</tr></thead><tbody>${rows
    .map(
      (row) =>
        `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join('')}</tr>`,
    )
    .join('')}</tbody></table></div>`;
};

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(leagueName)} — Preseason League Command Center</title>
<style>
:root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}
body{
  margin:0;
  background:
    radial-gradient(circle at top left,rgba(79,70,229,.10),transparent 34rem),
    linear-gradient(180deg,#f8fafc 0%,#eef2ff 100%);
  color:#1f2937;
}
main{max-width:1200px;margin:0 auto;padding:48px 20px 72px}
.hero{
  background:linear-gradient(135deg,#312e81 0%,#4338ca 100%);
  color:#f8fafc;
  border:1px solid rgba(255,255,255,.18);
  border-radius:20px;
  padding:30px;
  margin-bottom:22px;
  box-shadow:0 18px 45px rgba(49,46,129,.18);
}
h1{margin:0 0 8px;font-size:clamp(1.8rem,4vw,2.7rem);letter-spacing:-.03em}
h2{margin:32px 0 12px;font-size:1.25rem;color:#1e1b4b;letter-spacing:-.02em}
.meta{color:#e0e7ff}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}
.card{
  background:#ffffff;
  border:1px solid #dfe3ee;
  border-radius:16px;
  padding:16px;
  box-shadow:0 10px 28px rgba(49,46,129,.07);
}
.card span{
  display:block;
  color:#6b7280;
  font-size:.78rem;
  text-transform:uppercase;
  letter-spacing:.07em;
}
.card strong{display:block;margin-top:6px;font-size:1.15rem;color:#312e81}
.table-wrap{
  overflow:auto;
  border:1px solid #dfe3ee;
  border-radius:16px;
  background:#ffffff;
  box-shadow:0 10px 28px rgba(49,46,129,.06);
}
table{width:100%;border-collapse:collapse;background:#ffffff}
th,td{padding:11px 13px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap}
th{
  background:#eef2ff;
  color:#312e81;
  font-size:.76rem;
  text-transform:uppercase;
  letter-spacing:.06em;
}
tr:last-child td{border-bottom:0}
tr:hover td{background:#fafaff}
.pills{display:flex;flex-wrap:wrap;gap:8px}
.pill{
  background:#eef2ff;
  color:#312e81;
  border:1px solid #c7d2fe;
  border-radius:999px;
  padding:7px 11px;
  font-weight:600;
}
.empty{color:#6b7280;font-style:italic}
footer{margin-top:38px;color:#6b7280;font-size:.85rem}
@media (max-width:640px){
  main{padding:24px 12px 48px}
  .hero{padding:22px}
  th,td{padding:9px 10px}
}
</style>
</head>
<body><main>
<section class="hero">
<h1>${escapeHtml(leagueName)}</h1>
<p class="meta">Preseason League Command Center · Generated ${escapeHtml(generatedAt)}</p>
</section>
<section class="cards">
<div class="card"><span>Season</span><strong>${escapeHtml(league.season)}</strong></div>
<div class="card"><span>League Status</span><strong>${escapeHtml(league.status)}</strong></div>
<div class="card"><span>Teams</span><strong>${escapeHtml(league.total_rosters ?? rosters.length)}</strong></div>
<div class="card"><span>NFL Week</span><strong>${escapeHtml(nflState.week)}</strong></div>
<div class="card"><span>Drafts</span><strong>${escapeHtml(drafts.length)}</strong></div>
<div class="card"><span>Traded Picks</span><strong>${escapeHtml(tradedPicks.length)}</strong></div>
</section>
<h2>Selected Sleeper User</h2>
${htmlTable(
  ['Display Name', 'Username', 'User ID', 'League Team', 'Roster ID'],
  [[
    user.display_name,
    user.username,
    user.user_id,
    selectedRoster ? userTeamName(usersById.get(String(selectedRoster.owner_id))) : 'No matching roster',
    selectedRoster?.roster_id,
  ]],
)}
<h2>Teams and Rosters</h2>
${htmlTable(
  ['Roster', 'Team', 'Owner', 'Players', 'Starters', 'Reserve', 'Taxi', 'Record', 'Points For'],
  rosterRows.map((row) => [
    row.rosterId,
    row.team,
    row.owner,
    row.players,
    row.starters,
    row.reserve,
    row.taxi,
    row.record,
    row.pointsFor,
  ]),
)}
<h2>Drafts</h2>
${htmlTable(
  ['Season', 'Status', 'Type', 'Rounds', 'Teams', 'Start Time', 'Draft ID'],
  draftRows.map((row) => [
    row.season,
    row.status,
    row.type,
    row.rounds,
    row.teams,
    row.startTime,
    row.draftId,
  ]),
)}
<h2>Traded Draft Picks</h2>
${htmlTable(
  ['Season', 'Round', 'Original Roster', 'Previous Owner', 'Current Owner'],
  tradedPickRows.map((row) => [
    row.season,
    row.round,
    row.originalRoster,
    row.previousOwner,
    row.currentOwner,
  ]),
)}
<h2>Roster Sleeper League Form</h2>
<div class="pills">${rosterPositions.map((position) => `<span class="pill">${escapeHtml(position)}</span>`).join('')}</div>
<h2>Scoring Highlights</h2>
${htmlTable(['Setting', 'Value'], scoringHighlights.map((row) => [row.key, row.value]))}
<h2>League Settings</h2>
${htmlTable(['Setting', 'Value'], leagueSettings.map((row) => [row.key, row.value]))}
<footer>Generated with the unofficial n8n-nodes-sleeper community node. Sleeper data is public and read-only.</footer>
</main></body></html>`;

const safeName = String(leagueName)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60) || 'sleeper-league';

return [
  {
    json: {
      reportTitle: `${leagueName} — Preseason League Command Center`,
      generatedAt,
      filename: `${safeName}-preseason-command-center.html`,
      summary: {
        leagueId: asString(league.league_id ?? config.leagueId),
        leagueName,
        season: asString(league.season),
        leagueStatus: asString(league.status),
        nflWeek: asString(nflState.week),
        leagueUsers: leagueUsers.length,
        rosters: rosters.length,
        drafts: drafts.length,
        tradedPicks: tradedPicks.length,
        selectedUserId: asString(user.user_id),
        selectedRosterId: selectedRoster ? asString(selectedRoster.roster_id) : null,
      },
      markdown,
      html,
    },
  },
];
